def decimal_to_binary(decimal: int) -> str:
    if decimal < 0:
        raise ValueError("Decimal must be non-negative")

    binary_representation = ''
    if decimal == 0:
        binary_representation = '0'
    else:
        while decimal > 0:
            binary_representation = str(decimal % 2) + binary_representation
            decimal //= 2

    return f"db{binary_representation}db"

